from fastapi import FastAPI, File, Form, UploadFile
from fastapi.testclient import TestClient

app = FastAPI()

@app.post("/test-order")
async def test_order(form_data: str = Form(...), file: UploadFile = File(...)):
    return {"form_data": form_data, "file": file.filename}

client = TestClient(app)

def test_form_then_file():
    files = {"file": ("filename", "content")}
    data = {"form_data": "some data"}
    response = client.post("/test-order", data=data, files=files)
    print(f"Response: {response.status_code}, Body: {response.json()}")
    assert response.status_code == 200

def test_file_then_form():
    # This is the case that should work
    @app.post("/test-order-reversed")
    async def test_order_reversed(file: UploadFile = File(...), form_data: str = Form(...)):
        return {"form_data": form_data, "file": file.filename}

    files = {"file": ("filename", "content")}
    data = {"form_data": "some data"}
    response = client.post("/test-order-reversed", data=data, files=files)
    print(f"Response: {response.status_code}, Body: {response.json()}")
    assert response.status_code == 200

if __name__ == "__main__":
    try:
        test_form_then_file()
        print("test_form_then_file passed")
    except Exception as e:
        print(f"test_form_then_file failed: {e}")

    try:
        test_file_then_form()
        print("test_file_then_form passed")
    except Exception as e:
        print(f"test_file_then_form failed: {e}")

