async def test_order_1(file_val: bytes = File(...), form_val: str = Form(...)):
    return {"file": len(file_val), "form": form_val}

@app.post("/test-order-2")
async def test_order_2(form_val: str = Form(...), file_val: bytes = File(...)):
    return {"file": len(file_val), "form": form_val}

client = TestClient(app)

def test_reproduce():
    # This one should pass
    response1 = client.post(
        "/test-order-1",
        data={"form_val": "hello"},
        files={"file_val": b"world"}
    )
    assert response1.status_code == 200
    assert response1.json() == {"file": 5, "form": "hello"}

    # This one should fail with 422 if the bug exists
    response2 = client.post(
        "/test-order-2",
        data={"form_val": "hello"},
        files={"file_val": b"world"}
    )
    print(f"Response 2 status code: {response2.status_code}")
    print(f"Response 2 body: {response2.json()}")
    assert response2.status_code == 200
    assert response2.json() == {"file": 5, "form": "hello"}

if __name__ == "__main__":
    test_reproduce()

